mapper.select:
SELECT A.device_id, A.device_name, A.model_name, A.volte_num, A.keywords, A.company_id, B.company_code, A.car_num, A.update_date, A.maker_phone_1, A.maker_phone_2, A.reg_date, A.extra_info, A.created_by, A.updated_by, B.company_type AS user_type, B.company_name FROM TBL_ROUTER_INFO A LEFT JOIN TBL_COMPANY_INFO B ON A.COMPANY_ID = B.COMPANY_ID WHERE 1=1
AND device_id = #{tagId}
AND volte_num = #{volteNum}

SELECT COMPANY_TYPE AS USER_TYPE FROM tbl_company_info
WHERE 1=1

	AND COMPANY_ID = #{companyId}

GROUP BY COMPANY_TYPE;

